  "commands": [
    {
      "keystrokes": "cat > /tmp/read_skill.py << 'EOF'\nwith open('/tmp/skill.md', 'r') as f:\n    content = f.read()\nlines = content.split('\\n')\nfor i in range(0, len(lines), 30):\n    chunk = '\\n'.join(lines[i:i+30])\n    print(f'=== Lines {i+1}-{min(i+30, len(lines))} ===')\n    print(chunk)\n    print()\nEOF\\n",
      "duration": 0.2
